-- public.relic_use_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.relic_use_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_it item; v_skill text := p_target->>'skill'; v_name text; v_short text[];
begin
  v_it := carried(p_world, p_uid, target_item(p_target));
  if v_it.id is null then return 'It is gone.'; end if;
  if p_action = 'hone_whetstone' then
    if pack_count(p_world, p_uid, 'ancient_whetstone') <= 0 then return 'Need an ancient whetstone.'; end if;
    if unrestored(v_it.def) then return not_restored_says(); end if;
    if unmendable(v_it.def) then return unmendable_says(v_it.def); end if;
    if v_it.dmg <= 0 then return 'Not damaged.'; end if;
    return null;
  end if;
  if p_action = 'enchant_statue' then
    -- A restored statuette, a patron, and `statue_motes` of every element in the pack (`statueEnchantRefusal`).
    if v_it.def <> statuette() then
      return 'Restored ' || lower(coalesce((select d.name from item_def d where d.id = statuette()), statuette())) || 's only.';
    end if;
    if not exists (select 1 from patron_def pd where pd.id = p_target->>'patron') then return 'Choose a patron.'; end if;
    select array_agg(statue_motes() || ' ' || m.e || ' mote' || case when statue_motes() = 1 then '' else 's' end order by m.n)
      into v_short from unnest(mote_elements()) with ordinality m(e, n)
     where pack_count(p_world, p_uid, m.e || '_mote') < statue_motes();
    if v_short is not null then return 'Need ' || listed(v_short) || '.'; end if;
    return null;
  end if;
  if p_action = 'open_ferment' then
    -- A sealed vessel of a ferment, and its time come (`openFermentRefusal`).
    if v_it.def <> sealed_item() or not exists (select 1 from ferment_recipes() f where f.title = v_it.extra) then
      return 'It is gone.';
    end if;
    if coalesce(v_it.charges, 0) > world_time(p_world) then
      return 'Ready in ' || clock_left(v_it.charges - world_time(p_world)) || '.';
    end if;
    return null;
  end if;
  if p_action = 'serve_dish' then
    -- A dish for a group (`FEAST_ACTIONS`).
    if not exists (select 1 from serve_dishes() s where s.item = v_it.def) then return 'It is gone.'; end if;
    return null;
  end if;
  if p_action in ('read_recipe', 'read_formula') then
    -- A Recipe or a Formula, each read by its own action, and the recipe it opens not read yet (`readRecipeRefusal`).
    if v_it.def <> book_item(case p_action when 'read_formula' then 'formula' else 'recipe' end)
       or private.book_opens(v_it.def, v_it.extra) is null then return 'It is gone.'; end if;
    if private.recipe_read(p_world, p_uid, private.book_opens(v_it.def, v_it.extra)) then
      return book_known_says(book_of_item(v_it.def));
    end if;
    return null;
  end if;
  if p_action = 'open_seed_jar' then
    return case when v_it.def = 'ancient_seed_jar' then null else 'It is gone.' end;
  end if;
  if v_it.def <> 'rune_tablet' then return 'It is gone.'; end if;
  select d.name into v_name from skill_def d where d.id = v_skill;
  if v_skill is null or v_name is null then return 'Choose a skill in the Skills window.'; end if;
  if skill_standing(p_world, p_uid, v_skill) >= tablet_below() then
    return v_name || ': ' || tablet_below()::int || ' or over, nothing to learn.';
  end if;
  return null;
end $function$
